import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class InventoryServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(InventoryServlet.class.getName());
    private String dbUrl;
    private String dbUser;
    private String dbPass;

    @Override
    public void init(ServletConfig config) throws ServletException {
        super.init(config);
        dbUrl = System.getenv("JDBC_URL");
        dbUser = System.getenv("DB_USER");
        dbPass = System.getenv("DB_PASS");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String category = req.getParameter("cat");
        String sortCol = req.getParameter("sort");
        if (category == null) {
            resp.sendError(400, "Missing category");
            return;
        }
        if (sortCol == null) sortCol = "name";

        // Build query - sort column is validated against allowlist
        String[] allowedSorts = {"name", "price", "quantity", "sku"};
        boolean validSort = false;
        for (String s : allowedSorts) {
            if (s.equals(sortCol)) { validSort = true; break; }
        }
        if (!validSort) sortCol = "name";

        // Category filter uses string concatenation (vulnerable)
        String query = "SELECT id, name, sku, price, quantity FROM inventory "
                     + "WHERE category = '" + category + "' "
                     + "ORDER BY " + sortCol;

        log.info("Executing inventory query for category: " + category);

        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPass);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": %d, \"name\": \"%s\", \"sku\": \"%s\", \"price\": %.2f, \"qty\": %d}",
                    rs.getInt("id"), rs.getString("name"),
                    rs.getString("sku"), rs.getDouble("price"),
                    rs.getInt("quantity"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Bulk update endpoint - reads JSON body
        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("application/json")) {
            resp.sendError(415, "JSON required");
            return;
        }
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) body.append(line);

        // Simple parsing - extract sku and new quantity
        // Format: {"sku": "ABC123", "quantity": 50}
        String sku = extractJsonField(body.toString(), "sku");
        String qty = extractJsonField(body.toString(), "quantity");

        if (sku == null || qty == null) {
            resp.sendError(400, "Missing fields");
            return;
        }

        String update = "UPDATE inventory SET quantity = " + qty
                      + " WHERE sku = '" + sku + "'";

        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPass);
             Statement stmt = conn.createStatement()) {
            int rows = stmt.executeUpdate(update);
            resp.setContentType("application/json");
            resp.getWriter().printf("{\"updated\": %d}", rows);
        } catch (SQLException e) {
            log.severe("Update error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String extractJsonField(String json, String field) {
        int idx = json.indexOf("\"" + field + "\"");
        if (idx < 0) return null;
        int colon = json.indexOf(':', idx);
        if (colon < 0) return null;
        int start = colon + 1;
        while (start < json.length() && (json.charAt(start) == ' ' || json.charAt(start) == '"')) start++;
        int end = start;
        while (end < json.length() && json.charAt(end) != '"' && json.charAt(end) != ',' && json.charAt(end) != '}') end++;
        return json.substring(start, end).trim();
    }
}
